mapper.select:

WHERE rr.comp_id = #{storeId}
  AND DATE(STR_TO_DATE(rr.bill_date, '%Y-%m-%d %H:%i:%s')) BETWEEN #{startDate} AND #{endDate}
  AND rr.type = 0


WHERE rr.member_card_no = #{cardNo}
  AND DATE(STR_TO_DATE(rr.bill_date, '%Y-%m-%d %H:%i:%s')) < #{beforeDate}
  AND rr.type = 0
ORDER BY STR_TO_DATE(rr.bill_date, '%Y-%m-%d %H:%i:%s') ASC
